#pragma once

/** @file qemu_virt_dtb.hpp
 * @brief A real-world Flattened Device Tree blob, embedded as a byte array for
 * fdt_reader/fdt_index tests to decode against actual firmware-generated
 * output (not just hand-built test fixtures).
 *
 * Captured from QEMU's aarch64 `virt` machine model (4 vCPUs, 1 GiB RAM) via:
 *
 *   qemu-system-aarch64 -M virt,dumpdtb=devtree.dtb -cpu cortex-a57 -smp 4 -m 1G
 *
 * then repacked with `dtc -I dtb -O dtb -p 0` to strip QEMU's large trailing
 * padding region (QEMU pads to a full 1 MiB so firmware can grow the tree in
 * place; the padding carries no information and would otherwise bloat this
 * header for no benefit).
 */

